UPDATE documents
SET category = #{category},
    title = #{title},
    content = #{content},
    updated_at = SYSDATE,
    editor_user_id = #{isEditorUserId},
    is_pinned = #{isPinned}

    ,is_Comment = #{isComment}


    ,is_deleted = #{isDeleted}

WHERE document_id = #{documentId}

mapper.select:
SELECT b.* FROM (SELECT ROWNUM AS num, A.* FROM (SELECT COUNT(*) OVER() AS task_counts, d.title, u.user_name, d.created_at, d.is_pinned, d.is_deleted, d.is_comment, d.document_id, t.type_name, (SELECT count(*) FROM document_comments WHERE document_id = d.document_id AND is_deleted = 'Q2') AS count FROM documents d JOIN projects p ON d.project_id = p.project_id JOIN users u ON d.created_by = u.user_id LEFT JOIN task_types t ON d.category = t.task_type_id WHERE (p.project_id=#{projectId} OR p.parent_project_id = #{projectId}) AND d.is_deleted = 'Q2'
AND d.created_by = #{userId}
AND d.category = #{category}
AND d.created_at >= #{startDate}
AND d.created_at <= #{endDate}
AND d.title LIKE '%' || #{search} || '%'
ORDER BY d.is_pinned, d.created_at DESC) A WHERE ROWNUM BETWEEN 1 AND #{endNum})b WHERE b.num >= #{startNum}

